function retryAfterMs(res) {
  const h = res.headers.get("retry-after");
  if (!h) return null;
  if (!Number.isNaN(Number(h))) return Number(h) * 1000;   // "120"
  const at = Date.parse(h);                                 // HTTP-дата
  return Number.isNaN(at) ? null : Math.max(0, at - Date.now());
}
