async function fetchWithRetry(url, init = {}, { maxAttempts = 4, base = 500, cap = 8000 } = {}) {
  for (let attempt = 0; ; attempt++) {
    let res;
    try {
      res = await fetch(url, init);
    } catch (e) {
      if (e.name === "AbortError" || e.name === "TimeoutError") throw e; // отмену не повторяем
      if (attempt + 1 >= maxAttempts) throw e;                           // сетевая ошибка: повторим
    }
    if (res && (res.ok || !RETRYABLE.has(res.status) || attempt + 1 >= maxAttempts)) return res;

    const backoff = Math.random() * Math.min(cap, base * Math.pow(2, attempt)); // full jitter
    const wait = (res && retryAfterMs(res)) ?? backoff;   // Retry-After важнее своей формулы
    console.log("attempt " + (attempt + 1) + ": " + (res ? res.status : "network error") + ", wait " + Math.round(wait) + " ms");
    await sleep(wait, init.signal);                        // ожидание тоже отменяемо
  }
}

